package com.byawasaya.platform.plans;
import java.math.BigDecimal; import java.util.List; import java.util.UUID; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import com.byawasaya.platform.audit.AuditService;
@RestController
public class PlanController {
 private final PlatformPlanRepository plans; private final JdbcTemplate jdbc; private final AuditService audit;
 public PlanController(PlatformPlanRepository plans,JdbcTemplate jdbc,AuditService audit){this.plans=plans;this.jdbc=jdbc;this.audit=audit;}
 public record PlanRequest(@NotBlank @Pattern(regexp="[A-Z][A-Z0-9_]{2,39}")String code,@NotBlank @Size(max=100)String name,@Size(max=1000)String description,@NotNull @DecimalMin("0.00")BigDecimal monthlyPriceNpr,@NotNull @DecimalMin("0.00")BigDecimal annualPriceNpr,@Min(1)@Max(365)int trialDays,@Min(0)int maxProducts,@Min(1)int maxStaff,boolean published){}
 public record PlanResponse(UUID id,String code,String name,String description,BigDecimal monthlyPriceNpr,BigDecimal annualPriceNpr,int trialDays,int maxProducts,int maxStaff,boolean published){static PlanResponse from(PlatformPlan p){return new PlanResponse(p.getId(),p.getCode(),p.getName(),p.getDescription(),p.getMonthlyPriceNpr(),p.getAnnualPriceNpr(),p.getTrialDays(),p.getMaxProducts(),p.getMaxStaff(),p.isPublished());}}
 @GetMapping("/api/plans") public List<PlanResponse> publicPlans(){return plans.findByPublishedTrueOrderByMonthlyPriceNprAsc().stream().map(PlanResponse::from).toList();}
 @GetMapping("/api/platform/plans") public List<PlanResponse> all(){return plans.findAllByOrderByMonthlyPriceNprAsc().stream().map(PlanResponse::from).toList();}
 @PostMapping("/api/platform/plans") @ResponseStatus(HttpStatus.CREATED) public PlanResponse create(@Valid @RequestBody PlanRequest r,org.springframework.security.core.Authentication auth){if(plans.findByCodeIgnoreCase(r.code()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Plan code already exists.");PlatformPlan p=new PlatformPlan(r.code());p.update(r.name().trim(),r.description(),r.monthlyPriceNpr(),r.annualPriceNpr(),r.trialDays(),r.maxProducts(),r.maxStaff(),r.published());p=plans.save(p);audit.record(auth.getName(),"SUPERADMIN",null,"PLAN_CREATED","PLAN",p.getId().toString(),"SUCCESS","{}");return PlanResponse.from(p);}
 @PatchMapping("/api/platform/plans/{id}") public PlanResponse update(@PathVariable UUID id,@Valid @RequestBody PlanRequest r,org.springframework.security.core.Authentication auth){PlatformPlan p=plans.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Plan not found."));if(!p.getCode().equals(r.code()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Plan code is immutable after creation.");p.update(r.name().trim(),r.description(),r.monthlyPriceNpr(),r.annualPriceNpr(),r.trialDays(),r.maxProducts(),r.maxStaff(),r.published());p=plans.save(p);audit.record(auth.getName(),"SUPERADMIN",null,"PLAN_UPDATED","PLAN",id.toString(),"SUCCESS","{}");return PlanResponse.from(p);}
 @DeleteMapping("/api/platform/plans/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void archive(@PathVariable UUID id,org.springframework.security.core.Authentication auth){PlatformPlan p=plans.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Plan not found."));Long references=jdbc.queryForObject("SELECT (SELECT COUNT(*) FROM subscriptions WHERE plan_code=?)+(SELECT COUNT(*) FROM tenant_applications WHERE selected_plan_code=?)+(SELECT COUNT(*) FROM businesses WHERE plan=?)",Long.class,p.getCode(),p.getCode(),p.getCode());if(references!=null&&references>0){p.update(p.getName(),p.getDescription(),p.getMonthlyPriceNpr(),p.getAnnualPriceNpr(),p.getTrialDays(),p.getMaxProducts(),p.getMaxStaff(),false);plans.save(p);}else plans.delete(p);audit.record(auth.getName(),"SUPERADMIN",null,"PLAN_ARCHIVED_OR_DELETED","PLAN",id.toString(),"SUCCESS","{}");}
}
